import { readFileSync } from 'node:fs'
import { buildLGraphFromElkJson } from '../../../shared/elkgraph-builder.ts'
import { LayeredLayoutProvider } from '../../../src/layered-layout-provider.js'

/**
 * elkt 生成 (P3 JSON 路径): examples__edges__insideSelfLoops
 * 图: 2 节点 / 4 边 / 0 层级块
 */
describe('elkt 生成 (P3 JSON): examples__edges__insideSelfLoops', () => {
  const ELK_JSON = "{\"id\":\"root\",\"layoutOptions\":{\"org.eclipse.elk.direction\":\"RIGHT\",\"org.eclipse.elk.randomSeed\":\"1\"},\"children\":[{\"id\":\"Nparent\",\"width\":60,\"height\":30,\"layoutOptions\":{\"org.eclipse.elk.insideSelfLoops.activate\":\"true\",\"org.eclipse.elk.portConstraints\":\"FIXED_SIDE\"},\"ports\":[{\"id\":\"Nparent.p1\",\"width\":8,\"height\":8,\"x\":0,\"y\":0,\"properties\":{\"org.eclipse.elk.port.side\":\"WEST\"}},{\"id\":\"Nparent.p2\",\"width\":8,\"height\":8,\"x\":0,\"y\":0,\"properties\":{\"org.eclipse.elk.port.side\":\"EAST\"}}]},{\"id\":\"NparentWithSize\",\"width\":200,\"height\":100,\"layoutOptions\":{\"org.eclipse.elk.nodeSize.minimum\":\"100, 50\",\"org.eclipse.elk.nodeSize.constraints\":\"MINIMUM_SIZE\",\"org.eclipse.elk.insideSelfLoops.activate\":\"true\",\"org.eclipse.elk.portConstraints\":\"FIXED_SIDE\"},\"ports\":[{\"id\":\"NparentWithSize.p1\",\"width\":8,\"height\":8,\"x\":0,\"y\":0,\"properties\":{\"org.eclipse.elk.port.side\":\"WEST\"}},{\"id\":\"NparentWithSize.p2\",\"width\":8,\"height\":8,\"x\":0,\"y\":0,\"properties\":{\"org.eclipse.elk.port.side\":\"EAST\"}}]}],\"edges\":[{\"id\":\"e0\",\"sources\":[\"Nparent.p1\"],\"targets\":[\"Nparent.p2\"]},{\"id\":\"e1\",\"sources\":[\"Nparent.p1\"],\"targets\":[\"Nparent.p2\"],\"properties\":{\"org.eclipse.elk.insideSelfLoops.yo\":\"true\"}},{\"id\":\"e2\",\"sources\":[\"NparentWithSize.p1\"],\"targets\":[\"NparentWithSize.p2\"]},{\"id\":\"e3\",\"sources\":[\"NparentWithSize.p1\"],\"targets\":[\"NparentWithSize.p2\"],\"properties\":{\"org.eclipse.elk.insideSelfLoops.yo\":\"true\"}}]}"
  const NAMES: string[] = ["parent","parentWithSize"]
  it('P3 坐标级差分: 与 jar 0.12.0 1:1 对齐', () => {
    const { graph, nodeOf } = buildLGraphFromElkJson(JSON.parse(ELK_JSON))
    new LayeredLayoutProvider().layout(graph)
    if (false) {
      for (const n of nodeOf.values()) {
        expect(Number.isFinite(n.position.x)).toBe(true)
        expect(Number.isFinite(n.position.y)).toBe(true)
      }
      return
    }
    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/examples__edges__insideSelfLoops.json', import.meta.url), 'utf8'))
    expect(oracle.hash, 'jar oracle 过期/缺失, 请重跑 node scripts/generate-jar-oracle.mjs').toBe('d9ca028da6011059')
    const variants = oracle.variants ?? []
    for (let i = 0; i < NAMES.length; i++) {
      const gn = nodeOf.get(i)!
      const nm = 'N' + NAMES[i]
      const cands = [oracle.coords[nm], ...variants.map((v) => v.coords[nm])].filter(Boolean)
      expect(cands.length, nm + ' 缺少 jar oracle 坐标').toBeGreaterThan(0)
      const bestX = Math.min(...cands.map((c) => Math.abs(gn.position.x - c.x)))
      const bestY = Math.min(...cands.map((c) => Math.abs(gn.position.y - c.y)))
      expect(bestX, nm + ' x').toBeLessThanOrEqual(2)
      expect(bestY, nm + ' y').toBeLessThanOrEqual(2)
    }
  })
})

