describe('elkt 生成 (P3 JSON): examples__user-hints__model-order__modelOrderNoCrossingMin', () => {
  const ELK_JSON = "{\"id\":\"root\",\"layoutOptions\":{\"org.eclipse.elk.layered.crossingMinimization.strategy\":\"NONE\",\"org.eclipse.elk.layered.considerModelOrder.strategy\":\"NODES_AND_EDGES\",\"org.eclipse.elk.layered.crossingMinimization.greedySwitch.type\":\"OFF\",\"org.eclipse.elk.layered.nodePlacement.strategy\":\"SIMPLE\",\"org.eclipse.elk.direction\":\"RIGHT\",\"org.eclipse.elk.randomSeed\":\"1\"},\"children\":[{\"id\":\"Nn1\",\"width\":60,\"height\":30,\"labels\":[{\"text\":\"n1\",\"width\":0,\"height\":0}]},{\"id\":\"Nn2\",\"width\":60,\"height\":30,\"labels\":[{\"text\":\"n2\",\"width\":0,\"height\":0}]},{\"id\":\"Nn3\",\"width\":60,\"height\":30,\"labels\":[{\"text\":\"n3\",\"width\":0,\"height\":0}]},{\"id\":\"Nn4\",\"width\":60,\"height\":30,\"labels\":[{\"text\":\"n4\",\"width\":0,\"height\":0}]},{\"id\":\"Nn5\",\"width\":60,\"height\":30,\"labels\":[{\"text\":\"n5\",\"width\":0,\"height\":0}]}],\"edges\":[{\"id\":\"e0\",\"sources\":[\"Nn1\"],\"targets\":[\"Nn2\"]},{\"id\":\"e1\",\"sources\":[\"Nn1\"],\"targets\":[\"Nn3\"]},{\"id\":\"e2\",\"sources\":[\"Nn2\"],\"targets\":[\"Nn5\"]},{\"id\":\"e3\",\"sources\":[\"Nn3\"],\"targets\":[\"Nn4\"]}]}"
  const NAMES: string[] = ["n1","n2","n3","n4","n5"]
  it('P3 坐标级差分: 与 jar 0.12.0 1:1 对齐', () => {
    const { graph, nodeOf } = buildLGraphFromElkJson(JSON.parse(ELK_JSON))
    new LayeredLayoutProvider().layout(graph)
    if (false) {
      for (const n of nodeOf.values()) {
        expect(Number.isFinite(n.position.x)).toBe(true)
        expect(Number.isFinite(n.position.y)).toBe(true)
      }
      return
    }
    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/examples__user-hints__model-order__modelOrderNoCrossingMin.json', import.meta.url), 'utf8'))
    expect(oracle.hash, 'jar oracle 过期/缺失, 请重跑 node scripts/generate-jar-oracle.mjs').toBe('6ac861b13d70ea7b')
    const variants = oracle.variants ?? []
    for (let i = 0; i < NAMES.length; i++) {
      const gn = nodeOf.get(i)!
      const nm = 'N' + NAMES[i]
      const cands = [oracle.coords[nm], ...variants.map((v) => v.coords[nm])].filter(Boolean)
      expect(cands.length, nm + ' 缺少 jar oracle 坐标').toBeGreaterThan(0)
      const bestX = Math.min(...cands.map((c) => Math.abs(gn.position.x - c.x)))
      const bestY = Math.min(...cands.map((c) => Math.abs(gn.position.y - c.y)))
      expect(bestX, nm + ' x').toBeLessThanOrEqual(2)
      expect(bestY, nm + ' y').toBeLessThanOrEqual(2)
    }
  })
})

