    if (false) {
      for (const n of nodeOf.values()) {
        expect(Number.isFinite(n.position.x)).toBe(true)
        expect(Number.isFinite(n.position.y)).toBe(true)
      }
      return
    }
    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/tests__layered__north_south_ports__north_south_fixed_side.json', import.meta.url), 'utf8'))
