describe('elkt 生成 (P3 JSON): tickets__layered__700_brokenHierarchyHandling', () => {
  const ELK_JSON = "{\"id\":\"root\",\"layoutOptions\":{\"org.eclipse.elk.direction\":\"RIGHT\",\"org.eclipse.elk.randomSeed\":\"1\",\"org.eclipse.elk.hierarchyHandling\":\"INCLUDE_CHILDREN\"},\"children\":[{\"id\":\"Nn1\",\"width\":60,\"height\":30,\"layoutOptions\":{\"org.eclipse.elk.hierarchyHandling\":\"INCLUDE_CHILDREN\"},\"children\":[{\"id\":\"Nn1.n1_1\",\"width\":50,\"height\":50},{\"id\":\"Nn1.n1_2\",\"width\":50,\"height\":50}]},{\"id\":\"Nn2\",\"width\":60,\"height\":30,\"layoutOptions\":{\"org.eclipse.elk.hierarchyHandling\":\"INCLUDE_CHILDREN\"},\"children\":[{\"id\":\"Nn2.n2_1\",\"width\":60,\"height\":30,\"children\":[{\"id\":\"Nn2.n2_1.n2_1_1\",\"width\":50,\"height\":50},{\"id\":\"Nn2.n2_1.n2_1_2\",\"width\":50,\"height\":50}]}]}],\"edges\":[{\"id\":\"e0\",\"sources\":[\"Nn1.n1_1\"],\"targets\":[\"Nn1.n1_2\"]},{\"id\":\"e1\",\"sources\":[\"Nn2.n2_1.n2_1_1\"],\"targets\":[\"Nn2.n2_1.n2_1_2\"]}]}"
  const NAMES: string[] = ["n1","n1.n1_1","n1.n1_2","n2","n2.n2_1","n2.n2_1.n2_1_1","n2.n2_1.n2_1_2"]
  it('P3 坐标级差分: 与 jar 0.12.0 1:1 对齐', () => {
    const { graph, nodeOf } = buildLGraphFromElkJson(JSON.parse(ELK_JSON))
    new LayeredLayoutProvider().layout(graph)
    if (false) {
      for (const n of nodeOf.values()) {
        expect(Number.isFinite(n.position.x)).toBe(true)
        expect(Number.isFinite(n.position.y)).toBe(true)
      }
      return
    }
    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/tickets__layered__700_brokenHierarchyHandling.json', import.meta.url), 'utf8'))
    expect(oracle.hash, 'jar oracle 过期/缺失, 请重跑 node scripts/generate-jar-oracle.mjs').toBe('f4fcfd472ddbdaa6')
    const variants = oracle.variants ?? []
    for (let i = 0; i < NAMES.length; i++) {
      const gn = nodeOf.get(i)!
      const nm = 'N' + NAMES[i]
      const cands = [oracle.coords[nm], ...variants.map((v) => v.coords[nm])].filter(Boolean)
      expect(cands.length, nm + ' 缺少 jar oracle 坐标').toBeGreaterThan(0)
      const bestX = Math.min(...cands.map((c) => Math.abs(gn.position.x - c.x)))
      const bestY = Math.min(...cands.map((c) => Math.abs(gn.position.y - c.y)))
      expect(bestX, nm + ' x').toBeLessThanOrEqual(2)
      expect(bestY, nm + ' y').toBeLessThanOrEqual(2)
    }
  })
})

